'use client'

import * as React from 'react'

// The path is '../reward/reward' and not '../reward' on purpose: both items
// install into components/gamestage/<name>/, so this one specifier resolves the
// same in this repo and in a host application that ran `gamestage-ui add`.
import { Reward, type RewardProps } from './reward'
import { EmptyBoxGlyph } from './glyphs'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Inventory, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './inventory.css'

/**
 * Inventory: everything a player has, in one place.
 *
 * It is a collection of `reward` and nothing more. It does not fetch the
 * collection, does not sort it by any rule of its own, does not paginate and
 * does not claim anything. The host owns the list and its order; this renders
 * it and reports the press.
 *
 * The case that matters is the one nobody builds: an inventory with nothing in
 * it. A new player opens this before they have won anything, so the empty case
 * is the first thing most players see, and a blank rectangle at that moment
 * reads as a component that failed to load. It carries
 * `data-gs-empty="true"`, it renders a designed empty state, and its
 * accessible name says so.
 */

export interface InventoryProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** What this collection is. Rendered as the group's accessible name. */
  label: string
  /**
   * The rewards, in the order the host wants them. An empty array is the empty
   * case and renders as one.
   */
  rewards?: RewardProps[]
  /**
   * The line a player reads when they have nothing yet. The default is the
   * contract's word for `data-gs-empty`; a host with something better to say
   * about its own game should say it.
   */
  emptyLabel?: string
  /** Passed to every reward, so one handler opens whichever one is waiting. */
  onReveal?: (id: string) => void
}

/** The contract's word for `data-gs-empty`, in the name and on the screen. */
const EMPTY_LABEL = 'nothing here yet'

// The empty state's glyph is `EmptyBoxGlyph` from `@gamestage/glyphs`: an empty
// box, not a shrug, and drawn rather than typed. It was a colour emoji, which
// ignored every colour token and changed silhouette per operating system
// (GSUI-103). The character is not repeated here: the gate greps the source for
// emoji, and a mention would read as a use.

export function Inventory({
  label,
  rewards = [],
  emptyLabel = EMPTY_LABEL,
  onReveal,
  className,
  ...rest
}: InventoryProps) {
  const empty = rewards.length === 0

  // What it is, then how much of it there is. When there is none, the contract's
  // word rather than "0", because "0" is a count and this is an absence.
  const name = empty ? `${label}, ${EMPTY_LABEL}` : `${label}, ${rewards.length}`

  return (
    <div
      {...rest}
      className={['gs-inventory', className].filter(Boolean).join(' ')}
      data-gs-component="inventory"
      data-gs-empty={empty ? 'true' : undefined}
      // The count, machine-readable, beside whatever the collection renders.
      data-gs-value={rewards.length}
      role="group"
      aria-label={name}
    >
      {empty ? (
        // A designed empty state, never a blank rectangle. Emphasis, not motion:
        // there is nothing here to animate, and the glyph is the whole point.
        <p className="gs-inventory__empty" data-gs-scope="inventory" data-gs-part="empty" aria-hidden="true">
          <span className="gs-inventory__glyph" data-gs-scope="inventory" data-gs-part="glyph" data-gs-animates="emphasis">
            <EmptyBoxGlyph />
          </span>
          <span className="gs-inventory__empty-label" data-gs-scope="inventory" data-gs-part="label">
            {emptyLabel}
          </span>
        </p>
      ) : (
        // A real list, so a screen reader announces how many there are before
        // reading them. Only rendered when it has items: an empty <ul> around a
        // paragraph of empty-state copy is neither valid nor useful.
        <ul className="gs-inventory__list" data-gs-scope="inventory" data-gs-part="list">
          {rewards.map((reward) => (
            <li className="gs-inventory__item" key={reward.id}>
              <Reward {...reward} onReveal={reward.onReveal ?? onReveal} />
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

/* Inventory. Every value comes from a token; nothing here is a literal colour. */

.gs-inventory {
  display: block;
  padding: var(--gs-space-4);
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-surface);
  color: var(--gs-color-ink);
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
}

.gs-inventory__list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--gs-size-action-large), 1fr));
  gap: var(--gs-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

.gs-inventory__item { display: grid; }

/* The empty case is designed, not omitted. It occupies the space the rewards
   would, so an inventory does not collapse to nothing the moment it is empty
   and read as a component that failed to render. */
.gs-inventory__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  min-height: var(--gs-size-action-large);
  margin: 0;
  padding: var(--gs-space-8) var(--gs-space-4);
  border: var(--gs-stroke-ui) dashed var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  text-align: center;
}

.gs-inventory__glyph {
  font-size: var(--gs-size-icon-hero);
  line-height: 1;
  color: var(--gs-color-ink-secondary);
  /* Emphasis: it survives reduced motion, which is the only reason it is here
     rather than an animation. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-inventory__empty-label {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
}
